def split_key_value(pair):
    key, _, value = pair.partition('=')
    return key.strip(), value.strip()

def first_occurrences_only(text):
    seen = set()
    out = []
    for c in text:
        if c not in seen:
            seen.add(c)
            out.append(c)
    return ''.join(out)

def prefix_before_digit(text):
    for i, c in enumerate(text):
        if c.isdigit():
            return text[:i]
    return text
